import { encodeAbiParameters, encodeFunctionData, keccak256, parseAbi, parseTransaction,
  type TransactionSerializable } from "viem";
import { privateKeyToAccount } from "viem/accounts";
import type { Address, Hex } from "../../src/model.js";
import type { SmartAccountGaslessBlock, SmartAccountGaslessIntent, SmartAccountGaslessMaterialDescriptor } from
  "../../src/smart-account-gasless/model.js";
import type { SmartAccountGaslessMaterialValidatorPort } from "../../src/smart-account-gasless/ports.js";
import { saRegistry } from "../../src/smart-account-gasless/registry.js";
import { SA_DELEGATION_ARRAY_PARAMETER, SA_DELEGATION_TUPLE_PARAMETER, SA_INCREASED_SPENT_TOPIC,
  SA_REDEEMED_TOPIC, SA_SINGLE_DEFAULT, SA_TRANSFER_TOPIC } from "../../src/smart-account-gasless/chain/abi.js";
import type { DecodedSmartAccountDelegation } from "../../src/smart-account-gasless/chain/redemption.js";
import type { SaReceiptLog } from "../../src/smart-account-gasless/chain/abi.js";
import { SA_TEST_AT, SA_TEST_RECIPIENT, saTestIntent } from "./smart-account-gasless-fixtures.js";

export type Json = Record<string, any>;
export const SA_OUTER = privateKeyToAccount(`0x${"71".repeat(32)}`);
export const SA_AUTHORIZER = privateKeyToAccount(`0x${"72".repeat(32)}`);
export const SA_RUNTIME_EVIDENCE_SHA256 = "dede9d085919f4d1c8bc39c9d730e8f602be44c34d4a75f1071762bfc848cbb5";
export const SA_RUNTIME_CODES = {
  "0xdb9b1e94b5b69df7e401ddbede43491141047db3": "",
  "0x92bf12322527caa612fd31a0e810472bbb106a8f": "",
  "0xf100b0819427117ecf76ed94b358b1a5b5c6d2fc": "",
  "0xc2b0d624c1c4319760c96503ba27c347f3260f55": "",
  "0x1046bb45c8d673d4ea75321280db34899413c069": "",
  "0xe144b0b2618071b4e56f746313528a669c7e65c5": "",
  "0x474e3ae7e169e940607cc624da8a15eb120139ab": "",
  "0xde4f2fac4b3d87a1d9953ca5fc09fca7f366254f": "",
  "0x63c0c19a282a1b52b07dd5a65b58948a07dae32b": "",
  "0x833589fcd6edb6e08f4c7c32d4f71b54bda02913": "",
  "0x2ce6311ddae708829bc0784c967b7d77d19fd779": "",
} as const satisfies Readonly<Record<Address, Hex>>;
export const saWord = (value: bigint): Hex => `0x${value.toString(16).padStart(64, "0")}`;
export const saQuantity = (value: bigint | number): Hex => `0x${BigInt(value).toString(16)}`;
export const saAddressTopic = (value: Address): Hex => `0x${value.slice(2).padStart(64, "0")}`;

export function saTestBlock(number: bigint, timestamp?: bigint): SmartAccountGaslessBlock {
  return { numberAtomic: number.toString(), hash: saWord(number + 10_000n),
    timestampAtomic: (timestamp ?? (BigInt(Date.parse(SA_TEST_AT) / 1000) + number - 50_000_000n)).toString() };
}

export function saRawBlock(block: SmartAccountGaslessBlock, transactions: readonly Hex[] = []): Json {
  return { number: saQuantity(BigInt(block.numberAtomic)), hash: block.hash,
    timestamp: saQuantity(BigInt(block.timestampAtomic)), transactions };
}

export interface SmartAccountRedemptionFixture {
  readonly intent: SmartAccountGaslessIntent;
  readonly material: SmartAccountGaslessMaterialDescriptor;
  readonly root: DecodedSmartAccountDelegation;
  readonly child: DecodedSmartAccountDelegation;
  readonly permissionContext: Hex;
  readonly rootContext: Hex;
  readonly executionCallData: Hex;
  readonly calldata: Hex;
  readonly validator: SmartAccountGaslessMaterialValidatorPort;
}

/**
 * Public synthetic encoding fixture. Its validator is intentionally a descriptor stub: it proves that T3
 * consumes the neutral validator result exactly, while real caveat/signature validation remains T2/root proof.
 */
export function saRedemptionFixture(): SmartAccountRedemptionFixture {
  const intent = saTestIntent(), registry = saRegistry(8453);
  const root: DecodedSmartAccountDelegation = { delegate: intent.binding.sessionAddress,
    delegator: intent.binding.ownerAddress, authority: saWord(0n), caveats: [{ enforcer: registry.protocol.period.address,
      terms: intent.binding.periodTerms, args: "0x" }], salt: 1n, signature: "0x1234" };
  const child: DecodedSmartAccountDelegation = { delegate: SA_OUTER.address.toLowerCase() as Address,
    delegator: intent.binding.sessionAddress, authority: intent.binding.rootDelegationHash,
    caveats: [{ enforcer: registry.protocol.amount.address, terms: saWord(BigInt(intent.request.grossAtomic)), args: "0x" }],
    salt: 2n, signature: "0x" };
  const rootContext = encodeAbiParameters([SA_DELEGATION_ARRAY_PARAMETER], [[root]]) as Hex;
  const permissionContext = encodeAbiParameters([SA_DELEGATION_ARRAY_PARAMETER], [[child, root]]) as Hex;
  const transfer = encodeFunctionData({ abi: parseAbi(["function transfer(address to,uint256 amount)"]),
    functionName: "transfer", args: [SA_TEST_RECIPIENT, BigInt(intent.request.grossAtomic)] });
  const executionCallData = `${registry.token.address}${"0".repeat(64)}${transfer.slice(2)}` as Hex;
  const calldata = encodeFunctionData({ abi: parseAbi([
    "function redeemDelegations(bytes[] permissionContexts,bytes32[] modes,bytes[] executionCallDatas)",
  ]), functionName: "redeemDelegations", args: [[permissionContext], [SA_SINGLE_DEFAULT], [executionCallData]] });
  const material: SmartAccountGaslessMaterialDescriptor = { encodedRootHash: intent.binding.encodedRootHash,
    encodedChildHash: "1".repeat(64), permissionContextHash: "2".repeat(64), payloadHash: "3".repeat(64),
    requirementsHash: "4".repeat(64), materialHash: "5".repeat(64),
    rootDelegationHash: intent.binding.rootDelegationHash, childDelegationHash: saWord(99n), sealedAt: SA_TEST_AT };
  const validator: SmartAccountGaslessMaterialValidatorPort = { validate: async () => ({
    encodedRootHash: material.encodedRootHash, encodedChildHash: material.encodedChildHash,
    permissionContextHash: material.permissionContextHash, payloadHash: material.payloadHash,
    requirementsHash: material.requirementsHash, materialHash: material.materialHash,
    rootDelegationHash: material.rootDelegationHash, childDelegationHash: material.childDelegationHash,
  }) };
  return { intent, material, root, child, permissionContext, rootContext, executionCallData, calldata, validator };
}

export async function saSignedOuter(type: 0 | 1 | 2 | 3 | 4, calldata: Hex,
  intent = saTestIntent(), authorizationSigner = SA_AUTHORIZER): Promise<{ readonly hash: Hex; readonly rpc: Json }> {
  const common = { chainId: 8453, to: intent.binding.delegationManager, nonce: 7, gas: 400_000n,
    value: 0n, data: calldata }, fees = { maxFeePerGas: 2_000_000_000n, maxPriorityFeePerGas: 10n };
  let transaction: TransactionSerializable;
  if (type === 0) transaction = { ...common, type: "legacy", gasPrice: fees.maxFeePerGas };
  else if (type === 1) transaction = { ...common, type: "eip2930", gasPrice: fees.maxFeePerGas, accessList: [] };
  else if (type === 2) transaction = { ...common, ...fees, type: "eip1559", accessList: [] };
  else if (type === 3) transaction = { ...common, ...fees, type: "eip4844", accessList: [],
    maxFeePerBlobGas: 100n, blobVersionedHashes: [`0x01${"67".repeat(31)}`] };
  else transaction = { ...common, ...fees, type: "eip7702", accessList: [], authorizationList: [
    await authorizationSigner.signAuthorization({ chainId: 8453,
      contractAddress: saRegistry(8453).protocol.delegate.address, nonce: 33 }),
  ] };
  const raw = await SA_OUTER.signTransaction(transaction), parsed = parseTransaction(raw) as Json;
  const hash = keccak256(raw);
  const rpc: Json = { hash, chainId: "0x2105", type: saQuantity(type), nonce: "0x7",
    from: SA_OUTER.address.toLowerCase(), to: common.to, gas: saQuantity(common.gas), value: "0x0", input: calldata,
    r: saWord(BigInt(parsed.r)), s: saWord(BigInt(parsed.s)),
    ...(type === 0 ? { v: saQuantity(parsed.v) } : { v: saQuantity(BigInt(parsed.yParity)),
      yParity: saQuantity(BigInt(parsed.yParity)), accessList: parsed.accessList ?? [] }),
    ...(type < 2 ? { gasPrice: saQuantity(fees.maxFeePerGas) } : {
      maxFeePerGas: saQuantity(fees.maxFeePerGas), maxPriorityFeePerGas: saQuantity(fees.maxPriorityFeePerGas) }),
    ...(type === 3 ? { maxFeePerBlobGas: "0x64", blobVersionedHashes: parsed.blobVersionedHashes } : {}),
    ...(type === 4 ? { authorizationList: parsed.authorizationList.map((authorization: Json) => ({
      chainId: saQuantity(authorization.chainId), address: authorization.address.toLowerCase(),
      nonce: saQuantity(authorization.nonce), yParity: saQuantity(authorization.yParity),
      r: saWord(BigInt(authorization.r)), s: saWord(BigInt(authorization.s)),
    })) } : {}),
  };
  return { hash, rpc };
}

export function saReceiptLogs(fixture: SmartAccountRedemptionFixture, transactionHash: Hex,
  block: SmartAccountGaslessBlock, outer = SA_OUTER.address.toLowerCase() as Address): readonly SaReceiptLog[] {
  const registry = saRegistry(8453), gross = BigInt(fixture.intent.request.grossAtomic);
  const values: Array<{ address: Address; topics: readonly Hex[]; data: Hex }> = [
    { address: registry.token.address, topics: [SA_TRANSFER_TOPIC, saAddressTopic(fixture.intent.binding.ownerAddress),
      saAddressTopic(fixture.intent.request.recipient)], data: saWord(gross) },
    { address: registry.protocol.manager.address, topics: [SA_REDEEMED_TOPIC,
      saAddressTopic(fixture.intent.binding.ownerAddress), saAddressTopic(outer)],
      data: encodeAbiParameters([SA_DELEGATION_TUPLE_PARAMETER], [fixture.child]) },
    { address: registry.protocol.manager.address, topics: [SA_REDEEMED_TOPIC,
      saAddressTopic(fixture.intent.binding.ownerAddress), saAddressTopic(outer)],
      data: encodeAbiParameters([SA_DELEGATION_TUPLE_PARAMETER], [fixture.root]) },
    { address: registry.protocol.amount.address, topics: [SA_INCREASED_SPENT_TOPIC,
      saAddressTopic(registry.protocol.manager.address), saAddressTopic(outer), fixture.material.childDelegationHash],
      data: `${saWord(gross)}${saWord(gross).slice(2)}` as Hex },
  ];
  return values.map((value, index) => ({ ...value, logIndexAtomic: String(index), transactionHash }));
}

export function saRawReceiptLog(log: SaReceiptLog, transactionHash: Hex, block: SmartAccountGaslessBlock,
  transactionIndex = 0n): Json {
  return { address: log.address, topics: log.topics, data: log.data, logIndex: saQuantity(BigInt(log.logIndexAtomic)),
    transactionHash, blockHash: block.hash, blockNumber: saQuantity(BigInt(block.numberAtomic)),
    transactionIndex: saQuantity(transactionIndex), removed: false };
}
